package cn.bidcheck.verification.engine;

import cn.bidcheck.domain.Domain.Evidence;
import cn.bidcheck.verification.facts.StructuralFixtures;
import cn.bidcheck.verification.facts.TableStructure;
import java.util.*;
import org.junit.jupiter.api.Test;
import static cn.bidcheck.verification.engine.VerificationTypes.*;
import static org.junit.jupiter.api.Assertions.*;

class SourceBoundRecordNormalizationTest {
    static String id(){String prefix="11010119900101001";int[] weights={7,9,10,5,8,4,2,1,6,3,7,9,10,5,8,4,2};int sum=0;for(int i=0;i<17;i++)sum+=(prefix.charAt(i)-'0')*weights[i];return prefix+"10X98765432".charAt(sum%11);}
    StructuralFixtures.Fixture split(String raw){cn.bidcheck.verification.facts.StructuralFixtures.Fixture original=StructuralFixtures.row(1,false,false,id(),"2025-01");String text=original.text().replace(id(),raw);List<Map<String,Object>> cells=new ArrayList<>();for(java.util.Map<java.lang.String, java.lang.Object> c:original.cells()){Map<String,Object> copy=new LinkedHashMap<>(c);if(copy.get("text").equals(id()))copy.put("text",raw);cells.add(copy);}java.util.LinkedHashMap<java.lang.String, java.lang.Object> source=new LinkedHashMap<>(original.sources().get(0));source.put("evidence",new Evidence("d","合成.pdf",1,"PAGE",text,"chars:0-"+text.length(),1));return new StructuralFixtures.Fixture(cells,cn.bidcheck.compat.Java8Api.listOf(source),text);}
    @Test void identifierFragmentsAreJoinedOnlyInsideOneValidatedIdentityCell(){cn.bidcheck.verification.facts.StructuralFixtures.Fixture f=split(id().substring(0,13)+"\n"+id().substring(13));cn.bidcheck.verification.facts.TableStructure.Result result=TableStructure.analyze(StructuralFixtures.NAME,StructuralFixtures.ids(f),f.cells(),f.sources());assertTrue(result.valid(),result.toString());assertTrue(result.rows().get(0).strongIdentity());assertFalse(cn.bidcheck.compat.Java8Api.isBlank(result.rows().get(0).identifierFingerprint()));}
    @Test void roleTextOrInvalidChecksumCannotBecomeIdentity(){for(String raw:cn.bidcheck.compat.Java8Api.listOf("拟在本合同任职", id().substring(0,13)+"\n"+id().substring(13,17)+(id().endsWith("0")?"1":"0"), id().substring(0,13)+" / "+id().substring(13))){cn.bidcheck.verification.facts.StructuralFixtures.Fixture f=split(raw);assertEquals("STRUCTURE_IDENTITY_FIELD_INVALID",TableStructure.analyze(StructuralFixtures.NAME,StructuralFixtures.ids(f),f.cells(),f.sources()).issue(),raw);}}
    List<Map<String,Object>> queryCells(EvidenceCorpus corpus,int numberSpan){String[] headings={"资质证书编号","资质名称","资质等级"};List<Map<String,Object>> cells=new ArrayList<>();for(int c=1;c<=3;c++)cells.add(cell(corpus,1,c,1,headings[c-1],true));cells.add(cell(corpus,2,1,numberSpan,"D311099999",false));cells.add(cell(corpus,2,2,1,"建筑工程施工总承包",false));cells.add(cell(corpus,2,3,1,"二级",false));cells.add(cell(corpus,3,2,1,"建筑装修装饰工程专业承包",false));cells.add(cell(corpus,3,3,1,"贰级",false));return cells;}
    Map<String,Object> cell(EvidenceCorpus c,int row,int col,int span,String text,boolean header){cn.bidcheck.verification.engine.VerificationTypes.Source s=c.all.get(0);return linked("kind","TABLE_CELL","cellId","r"+row+"c"+col,"spanId","r"+row+"c"+col,"documentId",s.evidence().documentId(),"documentHash",s.documentHash(),"documentVersion",s.documentVersion(),"locationType","PAGE","location",1,"tableId","query","row",row,"column",col,"rowSpan",span,"columnSpan",1,"text",text,"source","OOXML_NATIVE","header",header,"headerCellIds",header?cn.bidcheck.compat.Java8Api.listOf():cn.bidcheck.compat.Java8Api.listOf("r1c"+col));}
    EvidenceCorpus query(){return new PersonnelCountRoleTest().corpus("本项目资格查询截图\n企业名称：合成施工有限公司\n资质证书编号 资质名称 资质等级\nD311099999 建筑工程施工总承包 二级\n建筑装修装饰工程专业承包 贰级\nhttps://licenses.gov.cn/query");}
    @Test void explicitSameTableMergedCellSupportsCertificateNumberAndNormalizesGrade(){cn.bidcheck.verification.engine.EvidenceCorpus c=query();java.util.List<cn.bidcheck.verification.engine.QualificationProofAssociation.Record> results=CertificateEvidenceRecords.qualificationQueries(c,"合成施工有限公司","建筑装修装饰工程专业承包",queryCells(c,2));assertEquals(1,results.size(),results.toString());assertEquals("D311099999",results.get(0).number());assertEquals("二级",results.get(0).grade());assertEquals(true,results.get(0).fields().get("inheritedCertificateNumber"));assertEquals(false,results.get(0).fields().get("crossPageInheritance"));}
    @Test void blankCellWithoutSpanAndWrongDocumentHashDoNotBorrowEarlierNumber(){cn.bidcheck.verification.engine.EvidenceCorpus c=query();assertTrue(CertificateEvidenceRecords.qualificationQueries(c,"合成施工有限公司","建筑装修装饰工程专业承包",queryCells(c,1)).isEmpty());java.util.List<java.util.Map<java.lang.String, java.lang.Object>> layout=queryCells(c,2);layout.stream().filter(v->v.get("row").equals(2)&&v.get("column").equals(1)).forEach(v->v.put("documentHash","different"));assertTrue(CertificateEvidenceRecords.qualificationQueries(c,"合成施工有限公司","建筑装修装饰工程专业承包",layout).isEmpty());}
    @Test void maskedNamesCannotBecomeSamePersonEvenInTheSameSource(){cn.bidcheck.verification.engine.EvidenceCorpus c=new PersonnelCountRoleTest().corpus("张*甲 张乙甲 证书资料");java.util.List<java.lang.String> refs=cn.bidcheck.compat.Java8Api.listOf(c.all.get(0).id());Fact a=new Fact("a","PERSON_ROLE","项目负责人","姓名","张*甲","张*甲","","","CURRENT_PROJECT",refs,cn.bidcheck.compat.Java8Api.mapOf()),b=new Fact("b","CERTIFICATE","张*甲","证书","证书","证书","","","CURRENT_PROJECT",refs,cn.bidcheck.compat.Java8Api.mapOf());assertFalse(new SubjectIdentity(cn.bidcheck.compat.Java8Api.listOf(a, b),c,cn.bidcheck.compat.Java8Api.listOf()).samePerson(a,b));}
}
